<?php require_once __DIR__.'/../includes/permissions.php'; ?>
<?php require_role('buyer');$s=db()->prepare("SELECT p.*,c.name category_name,u.name farmer_name,f.verification_status,(SELECT COALESCE(AVG(rating),0) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') rating,(SELECT COUNT(*) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') review_count FROM favorites fav JOIN products p ON p.id=fav.product_id JOIN categories c ON c.id=p.category_id JOIN farmers f ON f.id=p.farmer_id JOIN users u ON u.id=f.user_id WHERE fav.user_id=? ORDER BY fav.created_at DESC");$s->execute([user()['id']]);$products=$s->fetchAll();include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">Guardados</span><h1>Favoritos</h1></div></div><?php if(!$products):?><div class="empty-state"><i class="bi bi-heart display-4"></i><h4>Ainda não guardou produtos</h4><p class="text-muted">Use o coração nos cartões para criar a sua seleção.</p><a class="btn btn-primary" href="<?=base_path('marketplace.php')?>">Explorar produtos</a></div><?php else:?><div class="row g-4"><?php foreach($products as $p):?><div class="col-sm-6 col-lg-4"><?php include __DIR__.'/../includes/product-card.php';?></div><?php endforeach;?></div><?php endif;?></section></div><?php include __DIR__.'/../includes/footer.php';?>
